[Form]
public class NDXZertifikation extends FormRun
{
    NDXZertfikation ndxZertifikation;

    QueryBuildRange     qbrCurZertTable;
}

/// <summary>
/// DebuC 17.11.22
/// </summary>
public void init()
{
    ndxZertifikation = new NDXZertfikation();

    super();
}

/// <summary>
/// DebuC 17.11.22
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret;

    ret = super();
    qbrCurZertTable.value(SysQuery::valueNot(NDXZertTableAll.ZertId));
    NdxZertTableAssignment_ds.executeQuery();

    return ret;
}

/// <summary>
/// DebuC 17.11.22
/// </summary>
public void init()
{
    QueryBuildDataSource qbds;
    ;         

    super();          
    qbds = this.query().dataSourceTable(tableNum(NDXZertTable));
    qbds.clearLinks();
    qbds.addLink(fieldNum(NDXZertZertZuordnung, SlaveZertId), fieldNum(NDXZertTable, ZertId), NDXZertZertZuordnungLine_ds.name());             
}

/// <summary>
/// DebuC 17.11.22
/// </summary>
public void init()
{
    QueryBuildDataSource qbds;
    ;

    super();

    qbds = this.query().dataSourceTable(tableNum(NDXZertZertZuordnung));
    qbds.clearDynalinks();
    qbds.addDynalink(fieldNum(NDXZertZertZuordnung, SlaveZertId), NDXZertTableAll, fieldNum(NDXZertTable, ZertId));
}

/// <summary>
/// DebuC 17.11.22
/// </summary>
public void init()
{
    QueryBuildDataSource qbds, qbds2;
    ;

    super();

    qbrCurZertTable = this.query().dataSourceTable(tableNum(NDXZertTable)).addRange(fieldNum(NDXZertTable, ZertId));
    qbrCurZertTable.value(SysQuery::valueNot(NDXZertTableAll.ZertId));
    qbds = this.query().dataSourceTable(tableNum(NDXZertTable));  
    qbds2 = qbds.addDataSource(tableNum(NDXZertZertZuordnung));
    qbds2.clearLinks();
    qbds2.relations(false);
    qbds2.joinMode(JoinMode::NoExistsJoin);
    qbds2.fetchMode(QueryFetchMode::One2One);
    qbds2.addLink(fieldNum(NDXZertZertZuordnung, SlaveZertId), fieldNum(NDXZertTable, ZertId));

}

/// <summary>
/// DebuC 17.11.22
/// </summary>
public void init()
{
    QueryBuildDataSource qbds;
    ;

    super();

    qbds  = this.query().dataSourceTable(tableNum(NDXZertTable));
    qbds.clearLinks();
    qbds.relations(false);
    qbds.joinMode(JoinMode::InnerJoin);
    qbds.fetchMode(QueryFetchMode::One2One);
    qbds.addLink(fieldNum(NDXZertZertZuordnung, SlaveZertId), fieldnum(NDXZertTable, ZertId));

}

/// <summary>
/// DebuC 17.11.22
/// </summary>
public void clicked()
{
    ;
    this.enabled(false);

    super();

    ndxZertifikation.assignCertification(NDXZertTableAll, NDXZertTableAssignment);
    NDXZertTableAll_ds.reread();
    NDXZertTableAssignment_ds.reread();
    this.enabled(true);
}

/// <summary>
/// DebuC 17.11.22
/// </summary>
public void clicked()
{
    this.enabled(false);

    super();

    ndxZertifikation.reassignCertification(NDXZertZertZuordnungAssignment);

    this.enabled(true);
}
